{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE Maplemonk.Banana_Club_myntra_sjit_fact_items AS SELECT * FROM ( SELECT \"MYNTRA_SJIT\" AS MARKETPLACE, CAST(order_id_fk AS STRING) AS order_id_fk, CAST(seller_order_id AS STRING) AS seller_order_id, CAST(store_order_id AS STRING) AS store_order_id, CAST(order_line_id AS INT64) AS order_line_id, CAST(order_tracking_number AS STRING) AS order_tracking_number, CAST(sku_id AS STRING) AS sku_id, CAST(myntra_sku_code AS STRING) AS myntra_sku_code, CAST(seller_sku_code AS STRING) AS seller_sku_code, CAST(style_id AS INT64) AS style_id, UPPER(CAST(style_name AS STRING)) AS PRODUCT_NAME, COALESCE(CAST(a.style_name AS STRING),b.name) AS PRODUCT_NAME_FINAL, COALESCE(CAST(a.size AS STRING),b.size) AS SIZE, CAST(brand AS STRING) AS BRAND, UPPER(CAST(article_type AS STRING)) AS CATEGORY, UPPER(b.sub_category) SUB_CATEGORY, CAST(vendor_article_number AS STRING) AS SKU, CAST(state AS STRING) AS STATE, CAST(city AS STRING) AS CITY, CAST(zipcode AS STRING) AS zipcode, CAST(warehouse_id AS INT64) AS warehouse_id, CAST(seller_warehouse_id AS INT64) AS seller_warehouse_id, CAST(courier_code AS STRING) AS courier_code, CASE WHEN created_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(created_on, 1, 19))) END AS created_date, CASE WHEN packed_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(packed_on, 1, 19))) END AS packed_date, CASE WHEN inscanned_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(inscanned_on, 1, 19))) END AS inscanned_date, CASE WHEN shipped_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(shipped_on, 1, 19))) END AS shipped_date, CASE WHEN delivered_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(delivered_on, 1, 19))) END AS delivered_date, CASE WHEN cancelled_on = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(cancelled_on, 1, 19))) END AS cancelled_date, CASE WHEN rto_creation_date = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(rto_creation_date, 1, 19))) END AS rto_creation_date, CASE WHEN return_creation_date = \'\' THEN NULL ELSE DATE(PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', SUBSTR(return_creation_date, 1, 19))) END AS return_creation_date, CAST(total_mrp AS FLOAT64) AS total_mrp, CAST(seller_price AS FLOAT64) AS seller_price, CAST(final_amount AS FLOAT64) AS selling_price, CAST(1 AS INT64) AS QUANTITY, CAST(discount AS FLOAT64) AS discount, CAST(coupon_discount AS FLOAT64) AS coupon_discount, CAST(tax_recovery AS FLOAT64) AS tax_recovery, CAST(shipping_charge AS FLOAT64) AS shipping_charge, CAST(gift_charge AS FLOAT64) AS gift_charge, CAST(gt_charges AS FLOAT64) AS gt_charges, CAST(cancellation_reason AS STRING) AS cancellation_reason, CAST(order_status AS STRING) AS order_status, CAST(order_release_id AS STRING) AS order_release_id, b.image_link, ROW_NUMBER() OVER (PARTITION BY order_id_fk, seller_order_id ORDER BY created_on DESC) AS rw FROM MAPLEMONK.Banana_Club_myntra_custom_sjit_reports a LEFT JOIN ( select distinct SPLIT(product_code, \'_\')[OFFSET(0)] sku , name , image_url image_link , color style_no , upper(category_name) category , upper(description) sub_category , upper(size) size , mrp , base_price selling_price from maplemonk.banana_club_unicommerce_get_product_master where color <> \'\' qualify row_number() over(partition by lower(trim(SPLIT(product_code, \'_\')[OFFSET(0)])) order by 1 ) = 1 ) b on trim(lower(a.vendor_article_number)) = trim(lower(b.sku)) ) WHERE rw = 1;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            